const D = { energy: .55, scale: 1, density: .55, speed: 1, shafts: .6, fog: .55, hue: 20, x: .62, y: .84, style: 'oldgrowth', act: 'still', seed: 0, alpha: 1 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width, height);
const fr = i => { const q = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return q - Math.floor(q); };
const hw = h => ((h % 360) + 360) % 360;
const ho = P.hue - 20;
const L3 = (a, b, f) => [a[0] + (b[0]-a[0])*f, a[1] + (b[1]-a[1])*f, a[2] + (b[2]-a[2])*f];
const sh = c => [hw(c[0] + ho), c[1], c[2]];
const NR = 4;                                    // trunk ranks, 0 = farthest

const STY = {
  // coastal old growth: red-brown trunks, green-gold backlit fog, teal shade
  oldgrowth: { skT:[150,30,20], skB:[70,34,52], fog:[64,26,60], trk:[18,44,26], trkL:[26,40,46],
               shaft:[54,40,74], fern:[110,42,20], mote:[52,30,90], grain:20 },
  // moonlit nocturne: cold blue-silver, near-monochrome
  nocturne:  { skT:[228,44,10], skB:[214,32,30], fog:[212,26,40], trk:[220,30,14], trkL:[210,22,34],
               shaft:[204,26,58], fern:[216,34,12], mote:[206,18,82], grain:14 },
  // autumn gold hour: amber shafts, warm duff
  autumn:    { skT:[28,44,22], skB:[40,54,54], fog:[42,42,60], trk:[20,52,26], trkL:[34,54,50],
               shaft:[44,66,80], fern:[46,54,26], mote:[46,50,90], grain:24 },
  // ABSTRACTED sumi ink-wash: tonal washes, dry-brush trunks, no colour
  ink:       { skT:[30,6,88], skB:[30,4,80], fog:[30,3,84], trk:[30,8,20], trkL:[30,6,40],
               shaft:[30,4,70], fern:[30,10,26], mote:[30,4,40], grain:30 },
  // ABSTRACTED cyan blueprint: trunks as measured verticals, contour, no photo shading
  blueprint: { skT:[210,70,16], skB:[202,58,26], fog:[200,40,30], trk:[196,30,70], trkL:[188,24,86],
               shaft:[190,40,60], fern:[196,44,44], mote:[186,26,92], grain:6 }
};
const st = STY[P.style] || STY.oldgrowth;

const en = Math.max(0, Math.min(1, P.energy));
const fg = Math.max(0, Math.min(1, P.fog));
const wy = height * P.y;                          // forest floor line
const key = width + 'x' + height + '|' + P.style + '|' + P.seed + '|' + Math.round(P.hue) + '|' + P.scale.toFixed(2) + '|' + P.density.toFixed(2) + '|' + P.y.toFixed(3) + '|' + P.x.toFixed(3);

if (!S.sky || S.key !== key) {
  const W = Math.max(2, Math.ceil(width)), H = Math.max(2, Math.ceil(height));
  const mk = (w, h) => { const g = createGraphics(Math.max(2, Math.ceil(w)), Math.max(2, Math.ceil(h))); g.colorMode(g.HSB, 360, 100, 100, 100); return g; };
  if (S.sky) { S.sky.remove(); S.ranks.forEach(r => r.g.remove()); S.mist.remove(); }
  S.sky = mk(W, H); S.mist = mk(W, H);

  // background gloom: dark canopy up top, lit fog toward the floor
  const g = S.sky; g.noStroke();
  const cT = sh(st.skT), cB = sh(st.skB);
  for (let yy = 0; yy < H; yy++) { const c = L3(cT, cB, Math.pow(yy / H, .9)); g.fill(c[0], c[1], c[2]); g.rect(0, yy, W, 1); }

  const fogC = sh(st.fog), trkC = sh(st.trk), trkL = sh(st.trkL);
  const lit = P.x;                                // which side of each trunk catches light

  // --- trunk ranks: nearer = fewer, thicker, darker, lower haze ---
  S.ranks = [];
  for (let L = 0; L < NR; L++) {
    const near = L / (NR - 1);
    const haze = (1 - near) * (.5 + .4 * fg);
    const q = mk(W, H); q.noStroke();
    const nt = Math.floor((3 + near * 4) + P.density * (3 + near * 6));
    const baseTrk = L3(trkC, fogC, haze);
    const baseLit = L3(trkL, fogC, haze * .8);
    for (let i = 0; i < nt; i++) {
      const tx = ((fr(L * 40 + i * 3 + 7) + fr(L * 40 + i * 3 + 9) * .3) % 1) * (W + u * .3) - u * .15;
      const tw = u * (.03 + fr(L * 40 + i * 3 + 11) * .05) * (.4 + near * 1.4) * P.scale;
      const topY = wy - u * (.55 + fr(L * 40 + i * 3 + 13) * .5) * (.5 + near) * P.scale;
      const sway = (fr(i + L) - .5);
      // the trunk mass
      q.fill(baseTrk[0], baseTrk[1], baseTrk[2], 100);
      q.beginShape();
      q.vertex(tx - tw / 2, wy + u * .1);
      q.vertex(tx - tw * .42, topY);
      q.vertex(tx + tw * .42, topY);
      q.vertex(tx + tw / 2, wy + u * .1);
      q.endShape(q.CLOSE);
      if (!st.grain || P.style !== 'blueprint') {
        // bark striations + a lit edge
        const nb = Math.floor(4 + near * 6);
        for (let b = 0; b < nb; b++) {
          const bx = tx + (b / nb - .5) * tw * .9;
          const shade = b / nb < lit ? baseLit : L3(baseTrk, [0,0,0], .3);
          q.strokeWeight(Math.max(.6, tw * .05)); q.stroke(shade[0], shade[1], Math.max(2, shade[2]), 40 + 30 * near);
          q.line(bx + sway * u * .01, topY + u * .02, bx, wy);
        }
        q.noStroke();
        // rim light down the sunward edge
        const rx = tx + tw * (lit - .5);
        q.fill(baseLit[0], baseLit[1] * .7, Math.min(99, baseLit[2] + 10), (30 + 30 * near) * en);
        q.rect(rx, topY, Math.max(1, tw * .12), wy - topY);
      } else {
        // blueprint: centreline + measure ticks only
        q.strokeWeight(1); q.stroke(baseLit[0], baseLit[1], baseLit[2], 70);
        q.line(tx, topY, tx, wy); q.noStroke();
      }
    }
    // aerial veil so far ranks read as further back
    q.fill(fogC[0], fogC[1] * .8, fogC[2], haze * 60);
    q.rect(0, 0, W, H);
    S.ranks.push({ g: q, near: near });
  }

  // fog banks between the ranks (tileable so the scroll never seams)
  S.mist.noStroke();
  for (let i = 0; i < 14; i++) {
    const bx = fr(i * 5 + 61) * W, by = wy - u * (.05 + fr(i * 5 + 62) * .7);
    const bw = u * (.4 + fr(i * 5 + 63) * .9), bhh = u * (.05 + fr(i * 5 + 64) * .12);
    for (let rep = -1; rep <= 1; rep++) for (let kk = 0; kk < 4; kk++) {
      S.mist.fill(fogC[0], fogC[1] * (1 - kk * .12), Math.min(99, fogC[2] + kk * 3), (5 + 10 * fg) * (1 - kk * .2));
      S.mist.ellipse(bx + rep * W, by + kk * bhh * .1, bw * (1 - kk * .1), bhh * (1 - kk * .08));
    }
  }
  S.key = key;
}

// ---------------- act ----------------
const sec = ((Math.floor(K.section) % 6) + 6) % 6;
const ACT = { still: { sway: .4, dust: 1, fogk: 1 }, windgust: { sway: 1.3, dust: 1.8, fogk: 1.1 }, mistrise: { sway: .5, dust: 1.1, fogk: 1 + sec * .12 } };
const act = ACT[P.act] || ACT.still;
const drift = 0.9 * Math.sin(K.t * .21) + 0.5 * Math.sin(K.t * .53 + 1.7) + 0.3 * Math.sin(K.t * .97);

noStroke();
image(S.sky, 0, 0);

// far fog first (behind trunks)
const W2 = S.mist.width;
const mx = ((-K.t * u * .004 * P.speed % W2) + W2) % W2;
push(); tint(0, 0, 100, 60); image(S.mist, mx - W2, u * .04); image(S.mist, mx, u * .04); pop();

// the trunk ranks, farthest first, each drifting on its own rate (parallax)
for (let L = 0; L < NR; L++) {
  const r = S.ranks[L];
  const dx = (drift * .5 + Math.sin(K.t * (.05 + L * .017) + L) ) * u * .006 * (.3 + r.near) * act.sway;
  image(r.g, dx, Math.sin(K.t * (.03 + L * .009) + L * 2) * u * .001);
}

// near fog in front of nearer trunks
const mx2 = ((-K.t * u * .0075 * P.speed % W2) + W2) % W2;
push(); tint(0, 0, 100, 80 * act.fogk); image(S.mist, mx2 - W2, u * .12); image(S.mist, mx2, u * .12); pop();

// ---------------- volumetric light shafts raking down between trunks ----------------
const shC = sh(st.shaft);
if (P.style !== 'blueprint') {
  blendMode(ADD);
  const ns = Math.floor(3 + P.shafts * 4);
  for (let i = 0; i < ns; i++) {
    const sx = (fr(i * 7 + 81) * 1.1 - .05) * width + Math.sin(K.t * (.03 + i * .011) + i) * u * .02;
    const ang = (P.x - .5) * .5 + (fr(i * 7 + 82) - .5) * .3;
    const br = P.shafts * (.5 + .5 * Math.sin(K.t * (.12 + i * .05) + i * 1.7)) * (.6 + .4 * K.swell) + A.mid * .1;
    const top = -u * .1, len = wy - top + u * .1;
    for (let s = 0; s < 3; s++) {
      const wsh = u * (.03 + s * .05) * (.6 + P.shafts);
      fill(shC[0], shC[1] * (1 - s * .2), shC[2], (2.2 + 6 * br * en) * (1 - s * .25));
      beginShape();
      vertex(sx - wsh * .3, top); vertex(sx + wsh * .3, top);
      vertex(sx + wsh + ang * len, top + len); vertex(sx - wsh + ang * len, top + len);
      endShape(CLOSE);
    }
  }
  blendMode(BLEND);
}

// ---------------- fern / understory silhouette across the floor ----------------
const fernC = sh(st.fern);
noStroke();
fill(fernC[0], fernC[1], fernC[2] * .6, 100);
beginShape(); vertex(0, height);
for (let x = -10; x <= width + 10; x += u * .02) {
  const h = u * (.04 + .05 * (Math.sin(x * .01 + 1) * .5 + .5)) * (.6 + P.density);
  vertex(x, wy + u * .04 - h + Math.sin(x * .04) * u * .01);
}
vertex(width, height); endShape(CLOSE);
// a few fern fronds catching light
const nf = Math.floor(6 + P.density * 10);
for (let i = 0; i < nf; i++) {
  const fx = fr(i * 3 + 91) * width;
  const fh = u * (.05 + fr(i * 3 + 92) * .06) * (.7 + P.density);
  const bend = Math.sin(K.t * (.4 + i * .1) + i) * .12 * act.sway;
  strokeWeight(Math.max(.6, u * .002)); stroke(fernC[0], fernC[1] * .9, Math.min(70, fernC[2] + 20), 60);
  for (let side = -1; side <= 1; side += 2) {
    noFill(); beginShape();
    for (let t = 0; t <= 1; t += .12) {
      vertex(fx + side * fh * .5 * t + bend * fh * t, wy + u * .04 - fh * t - Math.sin(t * 3) * fh * .1);
    }
    endShape();
  }
}
noStroke();

// ---------------- dust motes / pollen drifting in the shafts (motion floor) ----------------
const moteC = sh(st.mote);
blendMode(ADD);
const nm = Math.floor(30 + P.density * 50);
for (let i = 0; i < nm; i++) {
  const life = ((K.t * (.02 + fr(i * 3 + 101) * .03) * P.speed * act.dust + fr(i * 3 + 102)) % 1);
  const mxp = (fr(i * 3 + 103) * width + Math.sin(K.t * (.2 + fr(i) * .3) + i) * u * .04) % width;
  const myp = height - life * height * 1.05;
  const near = fr(i * 3 + 104);
  const inShaft = .4 + .6 * (Math.sin(mxp * .01 + K.t * .1) * .5 + .5);
  fill(moteC[0], moteC[1] * .6, moteC[2], (8 + 20 * inShaft * en) * (1 - Math.abs(life - .5) * .8) * (.3 + near));
  ellipse(mxp, myp, u * .002 * (.5 + near * 1.5), u * .002 * (.5 + near * 1.5));
}
blendMode(BLEND);

// grain, vignette, alpha
if (st.grain > 6) {
  const ng = Math.floor(st.grain * 5);
  for (let i = 0; i < ng; i++) {
    const gx = ((fr(i * 3 + 201) * width) + Math.sin(K.t * .01 + i) * u * .002 + width) % width;
    const gy = fr(i * 3 + 202) * height;
    fill(st.skB[0], st.skB[1] * .4, fr(i * 3 + 203) > .5 ? 90 : 6, 3 + fr(i) * 5);
    rect(gx, gy, u * .0016, u * .0016);
  }
}
for (let i = 0; i < 5; i++) {
  noFill(); strokeWeight(u * .05);
  stroke(sh(st.skT)[0], st.skT[1], 5, 20 * (1 - i * .17));
  rect(-u * .03 + i * u * .03, -u * .03 + i * u * .03, width + u * .06 - i * u * .06, height + u * .06 - i * u * .06);
}
noStroke();
if (P.alpha < 1) { fill(sh(st.skT)[0], st.skT[1] * .5, 4, (1 - P.alpha) * 100); rect(0, 0, width, height); }
blendMode(BLEND);
drawingContext.shadowBlur = 0;
